Here is the commit message:
card-dnie: use size_t-specific format specifier in printf

Instead ogf blindly using "%lu", use "%"SC_FORMAT_LEN_SIZE_T"u"
to cope with the various implementations.

This fixes a bug introduced in commit 20b1d829

Here is the root cause:
The bug was caused by using the incorrect format specifier `"%lu"` for logging `size_t` values, which can lead to undefined behavior or incorrect output on platforms where `size_t` is not equivalent to `unsigned long`. This can result in misleading log messages regarding buffer sizes, potentially complicating debugging and error handling.

Here is the patch:

 static int dnie_sm_free_wrapped_apdu(struct sc_card *card,
 		struct sc_apdu *plain, struct sc_apdu **sm_apdu)
 {
 	struct sc_context *ctx = card->ctx;
 	cwa_provider_t *provider = NULL;
 	int rv = SC_SUCCESS;

 	LOG_FUNC_CALLED(ctx);
 	provider = GET_DNIE_PRIV_DATA(card)->cwa_provider;
 	if (!sm_apdu)
 		LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ARGUMENTS);
 	if (!(*sm_apdu))
 		LOG_FUNC_RETURN(ctx, SC_SUCCESS);

 	if ((*sm_apdu) != plain) {
 		rv = cwa_decode_response(card, provider, *sm_apdu);
 		if (plain && rv == SC_SUCCESS) {
 			if (plain->resp) {
 				/* copy the response into the original resp buffer */
 				if ((*sm_apdu)->resplen <= plain->resplen) {
 					memcpy(plain->resp, (*sm_apdu)->resp, (*sm_apdu)->resplen);
 					plain->resplen = (*sm_apdu)->resplen;
 				} else {
-					sc_log(card->ctx, "Invalid initial length, needed %lu bytes but has %lu",
+					sc_log(card->ctx, "Invalid initial length,"
+							" needed %"SC_FORMAT_LEN_SIZE_T"u bytes"
+							" but has %"SC_FORMAT_LEN_SIZE_T"u",
 							(*sm_apdu)->resplen, plain->resplen);
 					rv = SC_ERROR_BUFFER_TOO_SMALL;
 				}
 			}
 			plain->sw1 = (*sm_apdu)->sw1;
 			plain->sw2 = (*sm_apdu)->sw2;
 		}
 		free((unsigned char *) (*sm_apdu)->data);
 		free((*sm_apdu)->resp);
 		free(*sm_apdu);
 	}
 	*sm_apdu = NULL;

 	LOG_FUNC_RETURN(ctx, rv);
 }



